body.l-dashboard main {
  display: grid; grid-template-columns: repeat(4, 1fr); gap: 18px;
  max-width: 1080px; margin: 0 auto; padding: 40px 24px 24px;
}
body.l-dashboard main section {
  padding: 22px; margin: 0; max-width: none;
  border: 1.5px solid var(--border); background: var(--surface);
}
body.l-dashboard .section-desc, body.l-dashboard .skills-note { display: none; }
body.l-dashboard .section-title { font-size: 19px; margin-bottom: 6px; }
body.l-dashboard .section-tag { margin-bottom: 8px; padding: 2px 10px; font-size: 11.5px; }
body.l-dashboard #projects { grid-column: 1 / 3; grid-row: 1 / 3; }
body.l-dashboard #skills { grid-column: 3 / 5; }
body.l-dashboard #about { grid-column: 3 / 5; }
body.l-dashboard #blog { grid-column: 1 / 3; }
body.l-dashboard #contact { grid-column: 3 / 5; }
